func (s *Store) CreateMemoShare(ctx context.Context, create *MemoShare) (*MemoShare, error) {
	if create == nil {
		return nil, errors.New("memo share is required")
	}
	if err := validateMemoWritePolicy(create.Policy); err != nil {
